(function () {
  "use strict";

  const VERSION = 6;
  const SIZE = 17 + VERSION * 4;
  const DATA_CODEWORDS = 136;
  const BLOCKS = 2;
  const DATA_PER_BLOCK = 68;
  const EC_PER_BLOCK = 18;

  const EXP = new Array(512);
  const LOG = new Array(256);
  let x = 1;
  for (let i = 0; i < 255; i++) {
    EXP[i] = x;
    LOG[x] = i;
    x <<= 1;
    if (x & 0x100) x ^= 0x11d;
  }
  for (let i = 255; i < 512; i++) EXP[i] = EXP[i - 255];

  function mul(a, b) {
    if (a === 0 || b === 0) return 0;
    return EXP[LOG[a] + LOG[b]];
  }

  function generator(degree) {
    let poly = [1];
    for (let i = 0; i < degree; i++) {
      const next = new Array(poly.length + 1).fill(0);
      for (let j = 0; j < poly.length; j++) {
        next[j] ^= poly[j];
        next[j + 1] ^= mul(poly[j], EXP[i]);
      }
      poly = next;
    }
    return poly;
  }

  function rs(data, degree) {
    const gen = generator(degree);
    const out = new Array(degree).fill(0);
    data.forEach((byte) => {
      const factor = byte ^ out.shift();
      out.push(0);
      for (let i = 0; i < degree; i++) out[i] ^= mul(gen[i + 1], factor);
    });
    return out;
  }

  function utf8(text) {
    return Array.from(new TextEncoder().encode(text));
  }

  function pushBits(bits, value, length) {
    for (let i = length - 1; i >= 0; i--) bits.push((value >>> i) & 1);
  }

  function makeData(text) {
    const bytes = utf8(text);
    if (bytes.length > 134) throw new Error("URL ist fuer den eingebauten QR-Code zu lang.");
    const bits = [];
    pushBits(bits, 0b0100, 4);
    pushBits(bits, bytes.length, 8);
    bytes.forEach((b) => pushBits(bits, b, 8));
    const cap = DATA_CODEWORDS * 8;
    const term = Math.min(4, cap - bits.length);
    pushBits(bits, 0, term);
    while (bits.length % 8) bits.push(0);
    const data = [];
    for (let i = 0; i < bits.length; i += 8) {
      let v = 0;
      for (let j = 0; j < 8; j++) v = (v << 1) | bits[i + j];
      data.push(v);
    }
    for (let pad = 0; data.length < DATA_CODEWORDS; pad++) data.push(pad % 2 ? 0x11 : 0xec);
    return data;
  }

  function blank() {
    return {
      m: Array.from({ length: SIZE }, () => Array(SIZE).fill(false)),
      f: Array.from({ length: SIZE }, () => Array(SIZE).fill(false))
    };
  }

  function set(ctx, r, c, dark, func) {
    if (r < 0 || c < 0 || r >= SIZE || c >= SIZE) return;
    ctx.m[r][c] = !!dark;
    if (func) ctx.f[r][c] = true;
  }

  function finder(ctx, r, c) {
    for (let y = -1; y <= 7; y++) {
      for (let x = -1; x <= 7; x++) {
        const rr = r + y, cc = c + x;
        const inCore = x >= 0 && x <= 6 && y >= 0 && y <= 6;
        const dark = inCore && (x === 0 || x === 6 || y === 0 || y === 6 || (x >= 2 && x <= 4 && y >= 2 && y <= 4));
        set(ctx, rr, cc, dark, true);
      }
    }
  }

  function alignment(ctx, r, c) {
    for (let y = -2; y <= 2; y++) {
      for (let x = -2; x <= 2; x++) {
        set(ctx, r + y, c + x, Math.max(Math.abs(x), Math.abs(y)) !== 1, true);
      }
    }
  }

  function reserveFormat(ctx) {
    for (let i = 0; i <= 5; i++) { set(ctx, 8, i, false, true); set(ctx, i, 8, false, true); }
    set(ctx, 8, 7, false, true); set(ctx, 8, 8, false, true); set(ctx, 7, 8, false, true);
    for (let i = 9; i < 15; i++) set(ctx, 14 - i, 8, false, true);
    for (let i = 0; i < 8; i++) set(ctx, SIZE - 1 - i, 8, false, true);
    for (let i = 8; i < 15; i++) set(ctx, 8, SIZE - 15 + i, false, true);
  }

  function functionPatterns() {
    const ctx = blank();
    finder(ctx, 0, 0);
    finder(ctx, 0, SIZE - 7);
    finder(ctx, SIZE - 7, 0);
    for (let i = 8; i < SIZE - 8; i++) {
      set(ctx, 6, i, i % 2 === 0, true);
      set(ctx, i, 6, i % 2 === 0, true);
    }
    alignment(ctx, 34, 34);
    set(ctx, SIZE - 8, 8, true, true);
    reserveFormat(ctx);
    return ctx;
  }

  function codewords(text) {
    const data = makeData(text);
    const blocks = [];
    const ecc = [];
    for (let i = 0; i < BLOCKS; i++) {
      blocks.push(data.slice(i * DATA_PER_BLOCK, (i + 1) * DATA_PER_BLOCK));
      ecc.push(rs(blocks[i], EC_PER_BLOCK));
    }
    const out = [];
    for (let i = 0; i < DATA_PER_BLOCK; i++) for (let b = 0; b < BLOCKS; b++) out.push(blocks[b][i]);
    for (let i = 0; i < EC_PER_BLOCK; i++) for (let b = 0; b < BLOCKS; b++) out.push(ecc[b][i]);
    return out;
  }

  function placeData(ctx, words) {
    const bits = [];
    words.forEach((w) => pushBits(bits, w, 8));
    let i = 0;
    let up = true;
    for (let right = SIZE - 1; right >= 1; right -= 2) {
      if (right === 6) right--;
      for (let v = 0; v < SIZE; v++) {
        const r = up ? SIZE - 1 - v : v;
        for (let j = 0; j < 2; j++) {
          const c = right - j;
          if (!ctx.f[r][c]) ctx.m[r][c] = !!bits[i++];
        }
      }
      up = !up;
    }
  }

  function mask(maskId, r, c) {
    switch (maskId) {
      case 0: return (r + c) % 2 === 0;
      case 1: return r % 2 === 0;
      case 2: return c % 3 === 0;
      case 3: return (r + c) % 3 === 0;
      case 4: return (Math.floor(r / 2) + Math.floor(c / 3)) % 2 === 0;
      case 5: return ((r * c) % 2 + (r * c) % 3) === 0;
      case 6: return (((r * c) % 2 + (r * c) % 3) % 2) === 0;
      default: return (((r + c) % 2 + (r * c) % 3) % 2) === 0;
    }
  }

  function clone(ctx) {
    return { m: ctx.m.map((r) => r.slice()), f: ctx.f };
  }

  function applyMask(ctx, maskId) {
    for (let r = 0; r < SIZE; r++) for (let c = 0; c < SIZE; c++) {
      if (!ctx.f[r][c] && mask(maskId, r, c)) ctx.m[r][c] = !ctx.m[r][c];
    }
  }

  function formatBits(maskId) {
    let data = (1 << 3) | maskId;
    let rem = data;
    for (let i = 0; i < 10; i++) rem = (rem << 1) ^ (((rem >>> 9) & 1) ? 0x537 : 0);
    return ((data << 10) | (rem & 0x3ff)) ^ 0x5412;
  }

  function drawFormat(ctx, maskId) {
    const bits = formatBits(maskId);
    const bit = (i) => ((bits >>> i) & 1) !== 0;
    for (let i = 0; i <= 5; i++) set(ctx, 8, i, bit(i), true);
    set(ctx, 8, 7, bit(6), true);
    set(ctx, 8, 8, bit(7), true);
    set(ctx, 7, 8, bit(8), true);
    for (let i = 9; i < 15; i++) set(ctx, 14 - i, 8, bit(i), true);
    for (let i = 0; i < 8; i++) set(ctx, SIZE - 1 - i, 8, bit(i), true);
    for (let i = 8; i < 15; i++) set(ctx, 8, SIZE - 15 + i, bit(i), true);
    set(ctx, SIZE - 8, 8, true, true);
  }

  function penalty(ctx) {
    let p = 0;
    const scan = (line) => {
      let runColor = line[0], run = 1;
      for (let i = 1; i <= line.length; i++) {
        if (i < line.length && line[i] === runColor) run++;
        else {
          if (run >= 5) p += 3 + run - 5;
          runColor = line[i];
          run = 1;
        }
      }
      const s = line.map((v) => v ? "1" : "0").join("");
      for (let i = 0; i <= s.length - 11; i++) {
        const part = s.slice(i, i + 11);
        if (part === "10111010000" || part === "00001011101") p += 40;
      }
    };
    for (let r = 0; r < SIZE; r++) scan(ctx.m[r]);
    for (let c = 0; c < SIZE; c++) scan(ctx.m.map((row) => row[c]));
    for (let r = 0; r < SIZE - 1; r++) for (let c = 0; c < SIZE - 1; c++) {
      const v = ctx.m[r][c];
      if (ctx.m[r + 1][c] === v && ctx.m[r][c + 1] === v && ctx.m[r + 1][c + 1] === v) p += 3;
    }
    const dark = ctx.m.flat().filter(Boolean).length;
    p += Math.floor(Math.abs((dark * 100 / (SIZE * SIZE)) - 50) / 5) * 10;
    return p;
  }

  function matrix(text) {
    const base = functionPatterns();
    placeData(base, codewords(text));
    let best = null;
    let bestScore = Infinity;
    for (let i = 0; i < 8; i++) {
      const ctx = clone(base);
      applyMask(ctx, i);
      drawFormat(ctx, i);
      const score = penalty(ctx);
      if (score < bestScore) {
        bestScore = score;
        best = ctx;
      }
    }
    return best.m;
  }

  function svg(text, opts) {
    const m = matrix(text);
    const margin = opts && opts.margin != null ? opts.margin : 4;
    const view = SIZE + margin * 2;
    let path = "";
    for (let r = 0; r < SIZE; r++) for (let c = 0; c < SIZE; c++) {
      if (m[r][c]) path += `M${c + margin},${r + margin}h1v1h-1z`;
    }
    return `<svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="QR-Code" viewBox="0 0 ${view} ${view}" shape-rendering="crispEdges"><rect width="100%" height="100%" fill="#fff"/><path d="${path}" fill="#0E0E0C"/></svg>`;
  }

  window.VibeQR = {
    svg,
    render(el, text, opts) {
      el.innerHTML = svg(text, opts || {});
    }
  };
})();
